19	/// A polygon: the first ring is the outer contour, the rest are holes.
20	pub type Ring = [[f64; 2]];
21	
22	pub struct Earcut {
23	    nodes: Arena,
24	    pub indices: Vec<u32>,
25	    vertices: usize,
26	
27	    hashing: bool,
28	    min_x: f64,
29	    max_x: f64,
30	    min_y: f64,
31	    max_y: f64,
32	    inv_size: f64,
33	}
