35	impl Earcut {
36	    pub fn new() -> Earcut {
37	        Earcut {
38	            nodes: Arena::new(),
39	            indices: Vec::new(),
40	            vertices: 0,
41	            hashing: false,
42	            min_x: 0.0,
43	            max_x: 0.0,
44	            min_y: 0.0,
45	            max_y: 0.0,
46	            inv_size: 0.0,
47	        }
48	    }
